"""Dummy message classes used by tests and examples."""

from __future__ import annotations


class Message:
    """Container for lint message metadata."""

    message = ""

    def __init__(self, filename: str = "", loc: tuple[int, int] = (1, 0), use_column: bool = True):
        self.filename = filename
        self.lineno, self.col = loc
        self.use_column = use_column
        self.message_args: tuple[object, ...] = ()

    def __str__(self) -> str:
        text = self.message % self.message_args if self.message_args else self.message
        if self.use_column:
            return f"{self.filename}:{self.lineno}:{self.col}: {text}"
        return f"{self.filename}:{self.lineno}: {text}"


class UnusedImport(Message):
