"""Pylama TOML configuration."""

from __future__ import annotations

try:  # pragma: no cover - python 3.11+
    import tomllib as toml_lib
except ImportError:  # pragma: no cover - python < 3.11
    try:
        import tomli as toml_lib
    except ImportError:  # pragma: no cover - fallback for tests
        import toml as toml_lib  # type: ignore

from pylama.libs.inirama import Namespace as _Namespace


class Namespace(_Namespace):
    """Inirama-style wrapper for TOML config."""

    def parse(self, source: str, update: bool = True, **params):
        del params
        content = toml_lib.loads(source)
        pylama = content.get("tool", {}).get("pylama", {})
        if not isinstance(pylama, dict):
            return

        linters = dict(pylama.pop("linter", {}) or {})
        files = list(pylama.pop("files", []) or [])

        for name, value in pylama.items():
            if update or name not in self["pylama"]:
                self["pylama"][name] = value

        for linter, options in linters.items():
            if not isinstance(options, dict):
                continue
            section = self[f"pylama:{linter}"]
            for name, value in options.items():
                if update or name not in section:
                    section[name] = value

        for file_options in files:
            if not isinstance(file_options, dict):
                continue
            file_options = dict(file_options)
            path = file_options.pop("path", None)
            if path is None:
                continue
            section = self[f"pylama:{path}"]
            for name, value in file_options.items():
                if update or name not in section:
                    section[name] = value

