"""Pylama's shell support."""

from __future__ import annotations

import sys
import warnings
from json import dumps
from os import path as op
from os import walk
from pathlib import Path
from typing import List, Optional

from pylama import LOGGER
from pylama.check_async import check_async
from pylama.config import CURDIR, Namespace, parse_options, setup_logger
from pylama.core import run
from pylama.errors import Error
from pylama.utils import read_stdin

DEFAULT_FORMAT = "{filename}:{lnum}:{col} [{etype}] {number} {message} [{source}]"
MESSAGE_FORMATS = {
    "pylint": "{filename}:{lnum}: [{etype}] {number} {message} [{source}]",
    "pycodestyle": "{filename}:{lnum}:{col} {number} {message} [{source}]",
    "parsable": DEFAULT_FORMAT,
}


def _iter_candidates(paths: List[str]) -> List[str]:
    candidates = []
    seen = set()
    for raw_path in paths:
        if not op.exists(raw_path):
            continue
        if not op.isdir(raw_path):
            abspath = op.abspath(raw_path)
            if abspath not in seen:
                seen.add(abspath)
                candidates.append(abspath)
            continue
        for root, dirs, files in walk(raw_path):
            dirs.sort()
            files.sort()
            for filename in files:
                abspath = op.abspath(op.join(root, filename))
                if abspath not in seen:
                    seen.add(abspath)
                    candidates.append(abspath)
    return candidates


def check_paths(
    paths: Optional[List[str]],
    options: Namespace = None,
    code: str = None,
    rootdir: Path = None,
) -> List[Error]:
    """Check the given paths."""
    if options is None:
        options = parse_options(config=True, rootdir=rootdir or CURDIR)
    paths = paths or options.paths
    if not paths:
        return []
    if code is None:
        candidates = _iter_candidates(paths or options.paths)
    else:
        candidates = [paths[0]]
    if not candidates:
        return []

    if rootdir is None:
        first = Path(candidates[0])
        rootdir = first if first.is_dir() else first.parent

    candidates = [path for path in candidates if path.endswith(".py")]
    if options.concurrent:
        return check_async(candidates, code=code, options=options, rootdir=rootdir)

    errors: List[Error] = []
    for path in candidates:
        errors.extend(run(path=path, code=code, rootdir=rootdir, options=options))
    return errors


def check_path(options: Namespace, rootdir: str = None, candidates: List[str] = None, code: str = None) -> List[Error]:
    """Support legacy code."""
    warnings.warn(
        "pylama.main.check_path is deprecated and will be removed in pylama 9",
        DeprecationWarning,
        stacklevel=2,
    )
    return check_paths(
        candidates,
        code=code,
        options=options,
        rootdir=Path(rootdir) if rootdir else None,
    )


def display_errors(errors: List[Error], options: Namespace):
    """Format and display the given errors."""
    if options.format == "json":
        LOGGER.warning(dumps([err.to_dict() for err in errors]))
        return
    pattern = MESSAGE_FORMATS.get(options.format, DEFAULT_FORMAT)
    for err in errors:
        LOGGER.warning(err.format(pattern))


def shell(args: List[str] = None, error: bool = True):
    """Console endpoint."""
    if args is None:
        args = sys.argv[1:]
    options = parse_options(args)
    setup_logger(options)
    LOGGER.info(options)

    if options.hook:
        from pylama.hook import install_hook

        for path in options.paths:
            install_hook(path)
        return 0

    if options.from_stdin and not options.paths:
        LOGGER.error("--from-stdin requires a filename")
        if error:
            sys.exit(1)
        return []

    errors = check_paths(
        options.paths,
        code=read_stdin() if options.from_stdin else None,
        options=options,
        rootdir=CURDIR,
    )
    display_errors(errors, options)

    if error:
        sys.exit(int(bool(errors)))
    return errors


if __name__ == "__main__":  # pragma: no cover
    shell()

