"""Execution context for a single checked file."""

from __future__ import annotations

import ast
import os.path as op
import re
from argparse import Namespace
from copy import copy
from functools import lru_cache
from pathlib import Path
from tempfile import NamedTemporaryFile, mkdtemp
from typing import Any, Dict, Iterable, List, Set

from pylama.errors import Error
from pylama.utils import read

MODELINE_RE = re.compile(
    r"^\s*#\s+(?:pylama:)\s*((?:[\w_]*=[^:\n\s]+:?)+)", re.I | re.M
).search
SKIP_PATTERN = re.compile(r"# *noqa\b", re.I).search


def _split_values(value: Any) -> List[str]:
    if value in (None, ""):
        return []
    if isinstance(value, str):
        items = value.split(",")
    elif isinstance(value, Iterable):
        items = [str(item) for item in value]
    else:
        items = [str(value)]
    return [item.strip() for item in items if str(item).strip()]


class RunContext:  # pylint: disable=too-many-instance-attributes
    """Manage resources for a single run."""

    __slots__ = (
        "errors",
        "options",
        "skip",
        "ignore",
        "select",
        "linters",
        "linters_params",
        "filename",
        "_ast",
        "_from_stdin",
        "_source",
        "_tempfile",
        "_lines",
    )

    def __init__(self, filename: str, source: str = None, options: Namespace = None):
        self.errors: List[Error] = []
        self.options = options
        self.skip = False
        self.ignore: Set[str] = set()
        self.select: Set[str] = set()
        self.linters: List[str] = []
        self.linters_params: Dict[str, Dict[str, Any]] = {}
        self._ast = None
        self._from_stdin = source is not None
        self._source = source
        self._tempfile = None
        self._lines = None

        if options:
            if options.abspath:
                filename = op.abspath(filename)
            self.skip = bool(options.skip and any(ptrn.match(filename) for ptrn in options.skip))
            self.linters.extend(options.linters)
            self.ignore |= set(options.ignore)
            self.select |= set(options.select)
            self.linters_params.update(options.linters_params)
            for mask, params in options.file_params.items():
                if mask.match(filename):
                    self.update_params(**params)

        self.filename = filename

        if not self.skip:
            modeline = MODELINE_RE(self.source)
            if modeline:
                pairs = dict(value.split("=", 1) for value in modeline.group(1).split(":"))
                self.update_params(**pairs)

    def __enter__(self):
        return self

    def __exit__(self, etype, evalue, _traceback):
        if self._tempfile is not None:
            tmpfile = Path(self._tempfile)
            if tmpfile.exists():
                tmpfile.unlink()
            if tmpfile.parent.exists():
                tmpfile.parent.rmdir()

        if evalue is None:
            return True
        if etype is IOError:
            self.push(text=f"{evalue}", number="E001")
            return True
        if etype is UnicodeDecodeError:
            self.push(text=f"UnicodeError: {self.filename}", number="E001")
            return True
        if etype is SyntaxError:
            self.push(
                lnum=getattr(evalue, "lineno", 1) or 1,
                col=getattr(evalue, "offset", 1) or 1,
                text=f"SyntaxError: {evalue.args[0]}",
            )
            return True
        self.push(lnum=1, col=1, text=str(evalue))
        return False

    @property
    def source(self):
        if self._source is None:
            self._source = read(self.filename)
        return self._source

    @property
    def lines(self):
        if self._lines is None:
            self._lines = self.source.splitlines(True)
        return self._lines

    @property
    def ast(self):
        if self._ast is None:
            self._ast = compile(self.source, self.filename, "exec", ast.PyCF_ONLY_AST)
        return self._ast

    @property
    def temp_filename(self):
        if not self._from_stdin:
            return self.filename
        if self._tempfile is None:
            handle = NamedTemporaryFile(
                "w",
                encoding="utf8",
                suffix=".py",
                dir=mkdtemp(prefix="pylama_"),
                delete=False,
            )
            handle.write(self.source)
            handle.close()
            self._tempfile = handle.name
        return self._tempfile

    def update_params(self, ignore=None, select=None, linters=None, skip=None, **_):
        if select:
            self.select |= set(_split_values(select))
        if ignore:
            self.ignore |= set(_split_values(ignore))
        if linters:
            self.linters = _split_values(linters)
        if skip is not None:
            if isinstance(skip, bool):
                self.skip = skip
            else:
                self.skip = str(skip).strip().lower() in {"1", "true", "yes", "on"}

    @lru_cache(42)
    def get_params(self, name: str) -> Dict[str, Any]:
        params = copy(self.linters_params.get(name, {}))
        for key in ("ignore", "select"):
            if key in params and not isinstance(params[key], set):
                params[key] = set(_split_values(params[key]))
        return params

    @lru_cache(42)
    def get_filter(self, name: str, key: str) -> Set[str]:
        params = self.get_params(name)
        return set(params.get(key, set()))

    def push(self, filtrate: bool = True, **params):
        err = Error(filename=self.filename, **params)
        if len(self.lines) >= err.lnum and SKIP_PATTERN(self.lines[err.lnum - 1]):
            return None
        if filtrate:
            selected = self.select | self.get_filter(err.source, "select")
            if selected and not any(err.number.startswith(rule) for rule in selected if rule):
                return None
            ignored = self.ignore | self.get_filter(err.source, "ignore")
            if any(err.number.startswith(rule) for rule in ignored if rule):
                return None
        self.errors.append(err)
        return err

